<script setup lang="ts">
import DecorationCollection from './DecorationCollection.vue'
import DecorationMembershipPreview from './DecorationMembershipPreview.vue'
import {decorationIconUrl,decorationPreviewMember} from '../../../../api/src/core/decoration-framework.mjs'
import DecorationHeaderPreview from './DecorationHeaderPreview.vue'
import DecorationFrameworkPreview from './DecorationFrameworkPreview.vue'
import DecorationImagePlaceholder from './DecorationImagePlaceholder.vue'
import DecorationProfilePreview from './DecorationProfilePreview.vue'
import type {DecorationApplicationAssets,DecorationApplicationComponent,DecorationLink,DecorationScheme,DecorationBlock,DecorationMember,DecorationProfile} from '../../../../api/src/core/decoration-types'
import {decorationOuterStyle,decorationBlockStyle,decorationNavigation,decorationPageBackground,decorationTheme} from '../../../../api/src/core/decoration-contract.mjs'
import {galleryItems,galleryStyle,galleryItemStyle,galleryImageFit,galleryPlaceholder} from '../../../../api/src/core/decoration-options.mjs'
import DecorationExtraPreview from './DecorationExtraPreview.vue'
import {collectionContent,decorationRenderGroups,immersiveDecoration,decorationUnitStyle,floatStyle,dividerStyle} from '../../../../api/src/core/decoration-components.mjs'
import DecorationCarousel from './DecorationCarousel.vue'
import DecorationLinksPreview from './DecorationLinksPreview.vue'
import DecorationNoticePreview from './DecorationNoticePreview.vue'
const props=defineProps<{assets?:DecorationApplicationAssets;components?:DecorationApplicationComponent[];scheme:DecorationScheme;page:'home'|'profile';selected?:string;imageUrl:(id:string)=>string;editable?:boolean;miniProgram?:boolean;member?:DecorationMember|null;profile?:DecorationProfile|null}>()
defineEmits<{select:[id:string];selectPage:[];navigate:[target:DecorationLink];dropBlock:[id:string];drag:[id:string,event:PointerEvent]}>()
const resolveImage=(id:string)=>props.assets?.[id]?.web||props.imageUrl(id)
const previewMember=computed(()=>decorationPreviewMember(props.profile,props.member))
const pageData=computed(()=>props.scheme[props.page]),navigation=computed(()=>decorationNavigation(props.scheme))
const renderGroups=computed(()=>decorationRenderGroups(pageData.value.blocks))
const blockStyle=(b:DecorationBlock)=>decorationUnitStyle({...decorationBlockStyle(b,props.scheme,resolveImage),...(b.type==='float'?{margin:0,padding:0,background:'transparent'}:['membership','member-level','member-overview'].includes(b.type)?{background:'transparent',borderRadius:'0'}:{})})
function outerStyle(b:DecorationBlock,membership?:DecorationBlock){const memberOuter=membership?decorationOuterStyle(membership,props.scheme):null;return decorationUnitStyle({...decorationOuterStyle(b,props.scheme),...(memberOuter?{paddingTop:memberOuter.paddingTop,paddingLeft:memberOuter.paddingLeft,paddingRight:memberOuter.paddingRight}:{}),...(b.type==='float'?floatStyle(b,props.scheme.navigation.enabled,true):{})})}
</script>
<template><div class="decoration-preview" :class="{'is-immersive':immersiveDecoration(scheme,page),'framework-page':pageData.headerStyle==='framework'}" :style="{background:decorationPageBackground(scheme,page),'--client-primary':decorationTheme(scheme).primary,'--client-background':decorationTheme(scheme).background,'--client-muted':decorationTheme(scheme).muted,'--client-text':decorationTheme(scheme).text}"><DecorationHeaderPreview v-if="page==='home'&&pageData.showHeader===true" :page="pageData" :image-url="resolveImage" :editable="editable" :mini-program="miniProgram" @select-page="$emit('selectPage')" @navigate="$emit('navigate',$event)"/><div class="preview-content"><template v-for="{block,membership} in renderGroups" :key="block.id"><div v-if="block.enabled||editable" :data-block-id="membership?undefined:block.id" :data-block-type="block.type" class="preview-block-outer" :class="{'is-selected':selected===block.id,'is-hidden':!block.enabled,'is-editable':editable}" :style="outerStyle(block,membership) as any" :tabindex="editable?0:undefined" :role="editable?'button':undefined" :aria-label="editable?'选择'+(block.title||block.type):undefined" @pointerdown="editable&&$emit('drag',block.id,$event)" @dragstart.prevent @click="editable&&$emit('select',block.id)" @keydown.enter="editable&&$emit('select',block.id)" @dragover.prevent @drop.prevent.stop="editable&&$emit('dropBlock',block.id)"><div class="preview-block" :class="{'is-selected':selected===block.id}" :style="blockStyle(block) as any">
<template v-if="membership"><div class="joined-member" :class="{'is-selected':selected===membership.id}" :data-block-id="membership.id" :data-block-type="membership.type" :tabindex="editable?0:undefined" :role="editable?'button':undefined" :aria-label="editable?'选择'+membership.title:undefined" @pointerdown.stop="editable&&$emit('drag',membership.id,$event)" @click.stop="editable&&$emit('select',membership.id)" @keydown.enter.stop="editable&&$emit('select',membership.id)"><DecorationMembershipPreview merged :block="{...membership,options:{...membership.options,memberRadius:0}}" :member="previewMember" :image-url="resolveImage" :editable="editable" :primary="decorationTheme(scheme).primary" @navigate="$emit('navigate',$event)"/></div><div :data-block-id="block.id" :data-block-type="block.type"><DecorationMembershipPreview merged :block="block" :member="previewMember" :image-url="resolveImage" :editable="editable" :primary="decorationTheme(scheme).primary" @navigate="$emit('navigate',$event)"/></div></template><DecorationFrameworkPreview v-else-if="['intro','features','orders'].includes(block.type)" :block="block" :image-url="resolveImage" :editable="editable" @navigate="$emit('navigate',$event)"/><DecorationProfilePreview v-else-if="block.type==='profile'" :block="block" :profile="profile" :member="previewMember" :image-url="resolveImage" :editable="editable" @navigate="$emit('navigate',$event)"/><div v-else-if="block.type==='spacer'" :style="decorationUnitStyle({height:block.height+'px'})"/><hr v-else-if="block.type==='divider'" :style="decorationUnitStyle(dividerStyle(block))"/><DecorationExtraPreview v-else-if="['text','hot-area','rich-text','assets','membership','member-level','member-overview','activity','search-box','search','float','showcase'].includes(block.type)" :block="block" :editable="editable" :image-url="resolveImage" :member="previewMember" :primary="decorationTheme(scheme).primary" @navigate="$emit('navigate',$event)"/>
<div v-else-if="block.type==='wechat-ad'" class="flex min-h-24 flex-col items-center justify-center gap-2 border border-dashed border-blue-200 bg-blue-50/50 px-4 py-5 text-blue-600"><UIcon name="i-lucide-megaphone" class="size-6"/><span class="text-sm font-medium">微信横幅广告</span><span class="text-xs text-slate-500">预览占位 · 实际内容由微信提供</span></div><DecorationNoticePreview v-else-if="block.type==='notice'" :block="block" :editable="editable" :image-url="resolveImage" :primary="decorationTheme(scheme).primary" @navigate="$emit('navigate',$event)"/>
<button v-else-if="block.type==='button'" type="button" class="preview-cta" @click="!editable&&$emit('navigate',block.target)">{{block.title||'按钮'}}</button>
<img v-else-if="block.type==='image'" class="preview-image" :src="block.imageId?imageUrl(block.imageId):'/decoration/image-placeholder.svg'" :alt="block.title||'选择图片'" :draggable="false" @click="!editable&&$emit('navigate',block.target)">
<DecorationCarousel v-else-if="block.type==='banner'" :block="block" :editable="editable" :image-url="resolveImage" @navigate="$emit('navigate',$event)"/>
<div v-else-if="block.type==='gallery'" class="preview-gallery" :style="decorationUnitStyle(galleryStyle(block))"><button v-for="(item,index) in galleryItems(block)" :key="item.id" type="button" :style="decorationUnitStyle(galleryItemStyle(block,index))" @click="!editable&&$emit('navigate',item.target)"><img v-if="item.imageId||item.builtin" :src="resolveImage((item.imageId||item.builtin)!)" :alt="item.label" :style="{objectFit:galleryImageFit(block)}" :draggable="false"><DecorationImagePlaceholder v-else v-bind="galleryPlaceholder(block,index)"/></button></div>
<DecorationLinksPreview v-else-if="block.type==='links'" :block="block" :editable="editable" :image-url="resolveImage" @navigate="$emit('navigate',$event)"/><DecorationCollection v-else-if="block.type==='collection'||components?.some(c=>c.type===block.type&&c.renderer==='collection')" :block="block" :component="collectionContent(block,components)" :image-url="resolveImage"  :editable="editable" @navigate="$emit('navigate',$event)"/><slot v-else :block="block"/>
</div></div></template></div><div v-if="scheme.navigation.enabled" class="preview-navigation" :style="{background:navigation.background}"><button v-for="item in scheme.navigation.items" :key="item.id" type="button" :style="{color:item.target===page?navigation.selectedColor:navigation.color}" @click="$emit('navigate',item.target)"><img v-if="item.imageId||item.builtin||item.icon" :src="item.imageId?resolveImage(item.imageId):item.builtin?resolveImage(item.target===page&&item.selectedBuiltin?item.selectedBuiltin:item.builtin):decorationIconUrl(item.icon)" alt=""><UIcon v-else :name="item.target==='home'?'i-lucide-house':item.target==='profile'?'i-lucide-user-round':'i-lucide-layout-grid'" class="preview-nav-icon"/><span>{{item.label}}</span></button></div></div></template>
<style scoped>.decoration-preview{container-type:inline-size;--diy-unit:calc(100cqw / 375);position:relative;width:100%;min-height:620px;color:#172554;display:flex;flex-direction:column;overflow:hidden;font-size:14px}.preview-content{padding:0;flex:1}.preview-block-outer{position:relative;display:grid;min-width:0}.joined-member{position:relative}.joined-member::before{content:"";position:absolute;left:calc(var(--diy-unit,1px) * 16);right:calc(var(--diy-unit,1px) * 16);bottom:0;height:calc(var(--diy-unit,1px) * 1);background:#edf2f7;pointer-events:none}.joined-member.is-selected::after{content:"";position:absolute;inset:0;border:1px solid #2563eb;pointer-events:none;z-index:40}.preview-block{position:relative;overflow:hidden;overflow-wrap:anywhere}.preview-block-outer.is-editable{cursor:grab;touch-action:none;user-select:none}.preview-block.is-selected::after{content:"";position:absolute;inset:0;border:1px solid #2563eb;border-radius:inherit;box-sizing:border-box;pointer-events:none;z-index:40}.is-hidden{opacity:.4}.preview-heading{display:block;font-size:1.07em;font-weight:600;line-height:inherit}.preview-text{white-space:pre-wrap;margin:8px 0 0;line-height:inherit}.preview-image{display:block;width:100%;height:auto}.preview-gallery>button{border:0;padding:0;background:transparent;display:block;width:100%;height:100%}.preview-gallery img{display:block;width:100%;height:100%;object-fit:fill}.preview-cta{width:100%;min-height:24px;text-align:center;color:inherit;font:inherit;font-weight:600;border:0;background:transparent}.preview-block hr{border:0;border-top:1px solid;margin:0}.preview-navigation{height:50px;box-sizing:border-box;display:flex;align-items:center;justify-content:space-around;padding:4px 6px;border-top:1px solid #e2e8f0;flex-shrink:0}.preview-navigation button{border:0;background:none;display:flex;align-items:center;flex-direction:column;flex:1;gap:2px;cursor:pointer;color:inherit;min-width:0;font-size:10px;line-height:14px}.preview-navigation img,.preview-nav-icon{width:22px;height:22px;object-fit:contain}.preview-nav-icon{font-size:22px}.preview-navigation button>span:not(.iconify){max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.is-immersive>.preview-title{position:absolute;top:0;left:0;right:0;z-index:12}.framework-page .preview-navigation{height:calc(var(--diy-unit,1px)*56)}.framework-page .preview-navigation button{font-size:calc(var(--diy-unit,1px)*11)}.framework-page .preview-block-outer:has(.member-card){z-index:1}</style>
